+	__le32 ts_low;
+	__le32 ts_high;
+};
+
+struct line {
+	__le32 data_low;
+	__le32 data_high;
+};
+
+struct blk_tsline {
+	__le32 ts_low;
+	__le32 ts_high;
+};
+
+struct tsline {
+	__le32 data_low;
+	__le32 data_high;
